+.footer-col a{display:block;color:var(--gb-muted);padding:6px 0;font-weight:650}
+.footer-col a:hover{color:var(--gb-forest)}
+
+.footer-bottom{margin-top:18px;display:flex;flex-wrap:wrap;justify-content:space-between;gap:10px;color:var(--gb-muted);font-weight:650}
+
+.accordion-btn{
+  display:none;width:100%;
+  background:transparent;border:0;
+  padding:10px 0;
+  text-align:left;font-weight:900;color:var(--gb-forest);
+  cursor:pointer
+}
+.accordion-panel{display:block}
+
