+  max-width:var(--gb-max);margin:0 auto;
+}
+.cookie .card{padding:14px 14px;border-radius:20px}
+.cookie-top{display:flex;gap:14px;align-items:flex-start;justify-content:space-between}
+.cookie h3{margin:0;font-size:1.05rem}
+.cookie p{margin:6px 0 0;color:var(--gb-muted);line-height:1.5}
+.cookie-actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:12px}
+
+/* Utilities */
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
+
+.muted{color:var(--gb-muted)}
+.divider{height:1px;background:var(--gb-border);margin:14px 0}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-wrap{grid-template-columns:1fr}
+  .menu-layout{grid-template-columns:1fr}
+  .sidebar{position:relative;top:auto}
+  .tier-grid{grid-template-columns:1fr}
+  .locator{grid-template-columns:1fr}
+  .carousel-controls{position:static;margin-top:10px;justify-content:flex-end}
+}
+
+@media (max-width: 820px){
+  .nav{display:none}
+  .nav-toggle{display:inline-flex}
+  .nav-panel{display:none;border-top:1px solid var(--gb-border)}
+  .nav-panel.open{display:block}
+  .nav-panel a{display:block;padding:12px 0;color:var(--gb-forest);font-weight:800}
+  .header-inner{padding:12px 0}
+}
+
+@media (max-width: 720px){
+  .footer-grid{grid-template-columns:1fr}
+  .footer-col{border-bottom:1px solid var(--gb-border)}
+  .footer-col:last-child{border-bottom:0}
+  .accordion-btn{display:block}
+  .accordion-panel{display:none}
+  .footer-col[data-accordion-open="true"] .accordion-panel{display:block}
+}
+
+@media (prefers-reduced-motion: reduce){
+  *{scroll-behavior:auto !important;transition:none !important}
+}
+
